mapper.select:
SELECT announcement_type, COUNT(*) as count FROM sys_announcement WHERE status = 1
AND dept_id = #{deptId}
GROUP BY announcement_type

SELECT
    DATE(publish_time) as publish_date,
    COUNT(*) as count
FROM sys_announcement
WHERE status = 1
AND publish_time >= #{startTime}
AND publish_time <= #{endTime}

    AND dept_id = #{deptId}

GROUP BY DATE(publish_time)
ORDER BY publish_date ASC

SELECT a.id as announcement_id, a.title, a.announcement_type, a.publish_time, a.view_count as read_count, (SELECT COUNT(*) FROM sys_user WHERE status = 1) as total_users, (SELECT COUNT(*) FROM sys_user WHERE status = 1) - a.view_count as unread_count FROM sys_announcement a WHERE a.status = 1
AND a.id = #{announcementId}
ORDER BY a.publish_time DESC
